import {
  BaseSheet,
  FillRangeOperation,
  InsertColOperation,
  InsertRowOperation,
  UpdateMergeCellOperation,
  Operation,
  RemoveColOperation,
  RemoveRowOperation,
  Sheet,
  UpdateCellOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

const mergeRange = [8, 3, 9, 4];
describe.concurrent('left side to merge-cell right side to:', () => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: UpdateMergeCellOperation = {
    type: 'update-merge',
    uuid: 'm-rhufriT9HxxKzhjxw2wxCt',
    id: '1',
    newV: mergeRange,
  };
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', op12);
    console.log('op21,', op21);

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', JSON.stringify(doc1));
    console.log('doc2,', JSON.stringify(doc2));
    expect(doc1).toStrictEqual(doc2);
  });

  describe('update-cell', () => {
    test('in main cell', () => {
      op2 = {
        type: 'update-cell',
        at: [mergeRange[0], mergeRange[1]],
        newV: null,
        oldV: {
          value: 2,
        },
        id: '1',
      } as UpdateCellOperation;
      test('in side cell', () => {
        op2 = {
          type: 'update-cell',
          at: [mergeRange[0] + 1, mergeRange[1] + 1],
          newV: null,
          oldV: {
            value: 2,
          },
          id: '1',
        } as UpdateCellOperation;
      });
    });
  });

  describe('insert-row', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-row',
        at: 2,
        count: mergeRange[1] - 1,
        id: '1',
      } as InsertRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-row',
        at: 4,
        count: mergeRange[3] + 1,
        id: '1',
      } as InsertRowOperation;
    });
    test('at start', () => {
      op2 = {
        type: 'insert-row',
        at: 3,
        count: mergeRange[1],
        id: '1',
      } as InsertRowOperation;
    });
    test('at inner', () => {
      op2 = {
        type: 'insert-row',
        at: mergeRange[1] + 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
  });

  describe('remove-row', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-row',
        at: mergeRange[1] - 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: mergeRange[3] + 4,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at start', () => {
      op2 = {
        type: 'remove-row',
        at: mergeRange[1],
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at inner', () => {
      op2 = {
        type: 'remove-row',
        at: mergeRange[1] + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });

  describe('insert-col', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-col',
        at: mergeRange[0] - 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-col',
        at: mergeRange[2] + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at start', () => {
      op2 = {
        type: 'insert-col',
        at: mergeRange[0],
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at inner', () => {
      op2 = {
        type: 'insert-col',
        at: mergeRange[0] + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
  });

  describe('remove-col', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-col',
        at: mergeRange[0] - 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: mergeRange[2] + 4,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at start', () => {
      op2 = {
        type: 'remove-col',
        at: mergeRange[0],
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at inner', () => {
      op2 = {
        type: 'remove-col',
        at: mergeRange[0] + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });

  describe.concurrent('fill-range', () => {
    test('without intersection', () => {
      op2 = {
        type: 'fill-range',
        range: [3, 3, 5, 5],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('intersection main', () => {
      op2 = {
        type: 'fill-range',
        range: [7, 2, 8, 5],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('intersection side', () => {
      op2 = {
        type: 'fill-range',
        range: [9, 2, 12, 5],
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'fill-range',
        range: mergeRange,
        fillBy: 'style',
        style: {
          background: '#FAE1EB',
        },
        id: '1',
      } as FillRangeOperation;
    });
  });

  describe.concurrent('update-merge', () => {
    test('without intersection', () => {
      op2 = {
        type: 'update-merge',
        uuid: 'differ-uuid',
        id: '1',
        newV: [1, 2, 3, 4],
      } as UpdateMergeCellOperation;
    });
    test('intersection（difference uuid）', () => {
      op2 = {
        type: 'update-merge',
        uuid: 'differ-uuid',
        newV: [mergeRange[0], mergeRange[1], mergeRange[2] + 1, mergeRange[2] + 1],
        id: '1',
      } as UpdateMergeCellOperation;
    });
    test('intersection（same uuid）', () => {
      op2 = {
        type: 'update-merge',
        uuid: op1.uuid,
        newV: [mergeRange[0], mergeRange[1], mergeRange[2] + 1, mergeRange[2] + 1],
        id: '1',
      } as UpdateMergeCellOperation;
    });

    test('remove merge (difference uuid)', () => {
      op2 = {
        type: 'update-merge',
        uuid: 'differ-uuid',
        id: '1',
      } as UpdateMergeCellOperation;
    });

    test('remove merge (same uuid)', () => {
      op2 = {
        type: 'update-merge',
        uuid: op1.uuid,
        id: '1',
      } as UpdateMergeCellOperation;
    });
  });
});
